-- composition of rule kernels partitioned_execution x projection_pullup (duckdb), template cte_twice
WITH ka AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 5e-324::float8 AS c1, '00:00:00.000001'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, 10.0::float8 AS c1, MIN ('0'::interval) OVER (PARTITION BY 16) AS c2 FROM v0 AS a1), kb AS (SELECT DISTINCT 10::bigint AS c0, a1.c0 AS c1 FROM tl AS a1) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 5e-324::float8 AS c1, '00:00:00.000001'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, 10.0::float8 AS c1, MIN ('0'::interval) OVER (PARTITION BY 16) AS c2 FROM v0 AS a1) AS ka) + (SELECT count(*) FROM (SELECT DISTINCT 10::bigint AS c0, a1.c0 AS c1 FROM tl AS a1) AS kb)
